begin;
select no_plan();
insert into auth.users(id) values('82000000-0000-0000-0000-000000000001');
select set_config('request.jwt.claims','{"sub":"82000000-0000-0000-0000-000000000001"}',true);
select public.bootstrap_identity();select public.create_family();select public.adopt_cat('black_short','零点旅行猫');select public.adopt_cat('light_long','在家猫');
select set_config('test.home',family_id::text,true) from public.family_members where user_id=auth.uid();
select set_config('test.cat',id::text,true) from public.cats where name='零点旅行猫';
update public.cats set adopted_at='2026-08-01 00:00Z' where family_id=current_setting('test.home')::uuid;
insert into public.cat_trips values('82100000-0000-0000-0000-000000000001',current_setting('test.home')::uuid,current_setting('test.cat')::uuid,auth.uid(),'palace','2026-09-01 16:00:01Z','2026-09-02 16:00:01Z',now());
update public.wallets set miao_coins=-20 where owner_id=auth.uid();
select public.settle_family_day(current_setting('test.home')::uuid,'2026-09-02');
select is((select status from public.daily_cat_charges where cat_id=current_setting('test.cat')::uuid and business_day='2026-09-02'),'travel','end one second after midnight exempt even after late return');
select is((select due from public.daily_cat_charges where cat_id=current_setting('test.cat')::uuid and business_day='2026-09-02'),0,'travel no food or boarding');
select is((select paid from public.daily_interest_charges where owner_id=auth.uid() and business_day='2026-09-02'),2,'travel does not exempt debt interest');
select is((select miao_coins from public.wallets where owner_id=auth.uid()),-42,'other cat charged normally');
insert into public.cat_trips values('82100000-0000-0000-0000-000000000002',current_setting('test.home')::uuid,current_setting('test.cat')::uuid,auth.uid(),'fuji','2026-09-02 16:00Z','2026-09-03 16:00Z',now());
select public.settle_family_day(current_setting('test.home')::uuid,'2026-09-03');
select is((select due from public.daily_cat_charges where cat_id=current_setting('test.cat')::uuid and business_day='2026-09-03'),20,'exact midnight return not exempt');
insert into public.cat_trips values('82100000-0000-0000-0000-000000000003',current_setting('test.home')::uuid,current_setting('test.cat')::uuid,auth.uid(),'fuji','2026-09-03 15:59:59Z','2026-09-04 15:59:59Z',now());
select public.settle_family_day(current_setting('test.home')::uuid,'2026-09-04');
select is((select due from public.daily_cat_charges where cat_id=current_setting('test.cat')::uuid and business_day='2026-09-04'),20,'returned one second before midnight charged');
select * from finish();rollback;
